// SimpleStagger — main entry point
// SKSEPlugin_Version / SKSEPlugin_Query are generated by add_commonlibsse_plugin (CMakeLists.txt).
// Do NOT hand-write them here.

#include "Settings.h"
#include "HitHandler.h"
#include "MenuSMF.h"
#include "Resistance.h"

namespace {
    void InitializeLog()
    {
        auto path = SKSE::log::log_directory();
        if (!path) {
            SKSE::stl::report_and_fail("Failed to find standard logging directory"sv);
        }
        *path /= std::format("{}.log", "SimpleStagger");
        auto sink = std::make_shared<spdlog::sinks::basic_file_sink_mt>(path->string(), true);
        auto log  = std::make_shared<spdlog::logger>("global log"s, std::move(sink));
        log->set_level(spdlog::level::info);
        log->flush_on(spdlog::level::info);
        spdlog::set_default_logger(std::move(log));
        spdlog::set_pattern("[%H:%M:%S:%e] [%l] %v"s);
    }

    void MessageHandler(SKSE::MessagingInterface::Message* a_msg)
    {
        switch (a_msg->type) {

        case SKSE::MessagingInterface::kPostLoad:
            // Load INI settings as early as possible (forms not needed yet).
            (void) SimpleStagger::Settings::GetSingleton()->Load();
            break;

        case SKSE::MessagingInterface::kDataLoaded:
            // All forms are now loaded.
            // 1. Resolve override FormIDs and keyword EditorIDs.
            (void) SimpleStagger::Settings::GetSingleton()->ResolveOverrides();
            // 2. Detect and validate supported incoming-stagger perks.
            (void) SimpleStagger::InitializeIncomingStaggerPerkSupport();
            // 3. Register the TESHitEvent sink.
            SimpleStagger::HitHandler::Register();
            break;

        case SKSE::MessagingInterface::kPostLoadGame:
            // Clear per-target cooldown map after every save load.
            SimpleStagger::HitHandler::GetSingleton()->ClearCooldowns();
            break;

        default:
            break;
        }
    }
}  // namespace

SKSEPluginLoad(const SKSE::LoadInterface* a_skse)
{
    InitializeLog();

    SKSE::Init(a_skse, false);  // false = we own the logger

    SKSE::GetMessagingInterface()->RegisterListener(MessageHandler);

    // Register in-game settings menu (no-op if SKSEMenuFramework.dll is absent).
    SimpleStagger::MenuSMF::Register();

    logger::info("SimpleStagger loaded");

    return true;
}
